static uint8_t gnss_hdop_x10(const struct minmea_float *f)
{
  float h;
  unsigned v;

  if (f == NULL) {
    return 0;
  }

  h = minmea_tofloat(f);
  if (!isfinite(h) || h < 0.1f || h >= 50.0f) {
    return 0;
  }

  v = (unsigned)(h * 10.0f + 0.5f);
  return (uint8_t)(v > 255u ? 255u : v);
}

