void sf32lb_dvfs_boot(void)
{
  nxmutex_lock(&g_lock);
  g_hw_ready = true;
  g_holds |= SF32LB_DVFS_HOLD_BOOT;
  g_applied_mhz = 0;
  g_gov_mhz = SF32LB_DVFS_MHZ_240;
