98	static void status_bar_set_tone(lv_obj_t * ico, uint8_t tone)
99	{
100	    if (ico == NULL) {
101	        return;
102	    }
103	
104	    if (tone == SB_TONE_HIDE) {
105	        status_bar_show(ico, false);
106	        return;
107	    }
108	
109	    status_bar_show(ico, true);
110	    if (tone == SB_TONE_WAIT) {
111	        helm_icon_set_color(ico, lv_color_white());
112	    } else if (tone == SB_TONE_RED) {
113	        helm_icon_set_color(ico, helm_color(HELM_COLOR_GPS_DEAD));
114	    } else if (tone == SB_TONE_YEL) {
115	        helm_icon_set_color(ico, helm_color(HELM_COLOR_YEL));
116	    } else {
117	        helm_icon_set_color(ico, helm_color(HELM_COLOR_GPS));
118	    }
119	}
