121	static void status_bar_set_gps(const bicycle_runtime_t * rt)
122	{
123	    uint8_t tone;
124	    bool alive = rt && rt->gnss_alive;
125	    bool valid = rt && rt->gnss_valid;
126	    uint8_t q = rt ? rt->gnss_fix_quality : 0;
127	    uint8_t sats = rt ? rt->gnss_satellites : 0;
128	    uint8_t h = rt ? rt->gnss_hdop_x10 : 0;
129	
130	    if (!alive) {
131	        tone = SB_TONE_RED;
132	    } else if (!valid) {
133	        tone = SB_TONE_WAIT;
134	    } else if (q <= 1 || sats < 5 || h > 20) {
135	        tone = SB_TONE_YEL;
136	    } else {
137	        tone = SB_TONE_GREEN;
138	    }
139	
140	    if ((int)tone == s_last_gps) {
141	        return;
142	    }
143	
144	    s_last_gps = (int)tone;
145	    status_bar_set_tone(s_gps, tone);
146	}
