148	static void status_bar_set_phone(void)
149	{
150	    uint8_t tone;
151	
152	    if (!myvendor_devctl_radio_get()) {
153	        tone = SB_TONE_HIDE;
154	    } else if (myvendor_sys_phone_ble_connected()) {
155	        tone = SB_TONE_GREEN;
156	    } else {
157	        tone = SB_TONE_WAIT;
158	    }
159	
160	    if (s_ble == NULL || (int)tone == s_last_phone) {
161	        return;
162	    }
163	
164	    s_last_phone = (int)tone;
165	    status_bar_set_tone(s_ble, tone);
166	}
