168	static void status_bar_set_sensors(void)
169	{
170	    myvendor_devctl_sensor_rec_t recs[MYVENDOR_DEVCTL_SENSOR_REC_MAX];
171	    myvendor_sys_sensor_ui_t ui;
172	    size_t n = 0;
173	    size_t i;
174	    uint8_t k;
175	    bool want[MYVENDOR_SYS_SENSOR_KIND_N];
176	    bool sensor_on = myvendor_devctl_sensor_get();
177	
178	    for (k = 0; k < MYVENDOR_SYS_SENSOR_KIND_N; k++) {
179	        want[k] = false;
180	    }
181	
182	    if (sensor_on &&
183	        myvendor_devctl_sensor_recs_get(recs, MYVENDOR_DEVCTL_SENSOR_REC_MAX,
184	                                        &n) == 0) {
185	        for (i = 0; i < n; i++) {
186	            if (recs[i].autorc && recs[i].kind < MYVENDOR_SYS_SENSOR_KIND_N) {
187	                want[recs[i].kind] = true;
188	            }
189	        }
190	    }
191	
192	    myvendor_sys_sensor_ui_get(&ui);
193	
194	    for (k = 0; k < MYVENDOR_SYS_SENSOR_KIND_N; k++) {
195	        bool ready = (ui.slot[k].link == MYVENDOR_SYS_SENSOR_LINK_READY);
196	        uint8_t tone;
197	
198	        if (!sensor_on || !want[k]) {
199	            tone = SB_TONE_HIDE;
200	        } else if (ready) {
201	            tone = SB_TONE_GREEN;
202	        } else {
203	            tone = SB_TONE_WAIT;
204	        }
205	
206	        if (s_sns[k] == NULL || tone == s_last_sns[k]) {
207	            continue;
208	        }
209	
210	        s_last_sns[k] = tone;
211	        status_bar_set_tone(s_sns[k], tone);
212	    }
213	}
