233	static void status_bar_refresh(void)
234	{
235	    const bicycle_runtime_t * rt = bicycle_runtime_get();
236	    char buf[8];
237	    bool rec;
238	    bool nav;
239	    lv_color_t batt_c;
240	
241	    bicycle_status_bar_set_battery_pct(myvendor_sys_battery_percent());
242	
243	    {
244	        bool charging = (myvendor_sys_power_state() == MYVENDOR_SYS_PWR_CHARGING);
245	
246	        if (charging != (s_last_chg == 1)) {
247	            s_last_chg = charging ? 1 : 0;
248	            status_bar_set_batt_chrome(charging);
249	            s_last_batt = -1;
250	        }
251	    }
252	
253	    status_bar_set_gps(rt);
254	    status_bar_set_phone();
255	    status_bar_set_sensors();
256	
257	    if (s_time_lbl) {
258	        time_t now = time(NULL);
259	        int hour = -1;
260	        int min = -1;
261	
262	        if (now >= 1704067200) {
263	            if (!myvendor_devctl_tz_hms((long)now, &hour, &min)) {
264	                hour = -1;
265	                min = -1;
266	            }
267	        }
268	
269	        if (hour < 0) {
270	            myvendor_sys_gnss_t cfix;
271	            bool got = myvendor_sys_onboard_gnss_get(&cfix);
272	
273	            if (!got) {
274	                got = myvendor_sys_phone_gnss_get(&cfix);
275	            }
276	
277	            if (got && cfix.utc_sec >= 1704067200u) {
278	                time_t utc = (time_t)cfix.utc_sec;
279	                struct timeval tv;
280	
281	                tv.tv_sec = utc;
282	                tv.tv_usec = 0;
283	                (void)settimeofday(&tv, NULL);
284	                if (!myvendor_devctl_tz_hms((long)utc, &hour, &min)) {
285	                    hour = -1;
286	                    min = -1;
287	                }
288	            }
289	        }
290	
291	        if (hour < 0) {
292	            (void)bicycle_gpx_sim_get_wall_hms(&hour, &min);
293	        }
294	
295	        if (hour < 0) {
296	            hour = 0;
297	            min = 0;
298	        }
299	
300	        {
301	            const uint16_t hm = (uint16_t)(hour * 60 + min);
302	
303	            if (hm != s_last_time_hm) {
304	                lv_snprintf(buf, sizeof(buf), "%02d:%02d", hour, min);
305	                lv_label_set_text(s_time_lbl, buf);
306	                s_last_time_hm = hm;
307	            }
308	        }
309	    }
310	
311	    rec = rt && rt->recording;
312	    nav = map_page_nav_active(live_map_page_instance());
313	
314	    if (s_pill_rec && rec != s_last_rec) {
315	        s_last_rec = rec;
316	        status_bar_show(s_pill_rec, rec);
317	    }
318	
319	    if (s_pill_nav && nav != s_last_nav) {
320	        s_last_nav = nav;
321	        status_bar_show(s_pill_nav, nav);
322	    }
323	
324	    {
325	        bool paused = helm_shell_paused();
326	
327	        if (s_pill_pause && paused != s_last_pause) {
328	            s_last_pause = paused;
329	            status_bar_show(s_pill_pause, paused);
330	        }
331	    }
332	
333	
334	    if (s_batt_fill) {
335	        if (s_battery_pct >= 0) {
336	            if (s_battery_pct != s_last_batt) {
337	                lv_coord_t w = (lv_coord_t)lv_map(s_battery_pct, 0, 100, 0,
338	                                                  SB_BATT_FILL_MAX);
339	
340	                if (s_battery_pct > 0 && w < 2) {
341	                    w = 2;
342	                }
343	
344	                lv_obj_set_width(s_batt_fill, w);
345	                if (s_battery_pct <= 15) {
346	                    batt_c = helm_color(HELM_COLOR_GPS_DEAD);
347	                } else if (s_battery_pct <= 35) {
348	                    batt_c = helm_color(HELM_COLOR_BATT_MID);
349	                } else {
350	                    batt_c = helm_color(HELM_COLOR_GPS);
351	                }
352	
353	                lv_obj_set_style_bg_color(s_batt_fill, batt_c, 0);
354	                s_last_batt = s_battery_pct;
355	            }
356	        } else if (s_last_batt != -2) {
357	            lv_obj_set_width(s_batt_fill, 0);
358	            s_last_batt = -2;
359	        }
360	    }
361	}
