struct bicycle_gnss_fix;

typedef struct {
    /** @brief 最新 GNSS 定位。 */
    float longitude;
    float latitude;
    float altitude_m;
    bool has_altitude;
    float gnss_altitude_m;
    bool gnss_has_altitude;
    float gain_m;
    float loss_m;
    float grade_pct;
    bool gnss_valid;
    bool gnss_alive;
    bool gnss_eph_busy;
    uint8_t gnss_satellites;
    uint8_t gnss_fix_quality;
    uint8_t gnss_hdop_x10;
    uint8_t gnss_rx_hz;

    /** @brief GNSS 航向（度，0–360）。 */
    float course_deg;
    /** @brief 沿轨迹的当前运动方位（度，0–360）。 */
    float motion_deg;
    float speed_kph;
    float speed_max_kph;

    uint16_t hr_bpm;
    uint16_t hr_avg_bpm; /**< 录制中有效心率的会话平均。 */
    uint16_t hr_max_bpm; /**< 录制中有效心率的会话最大。 */
    uint16_t cadence_rpm;
    uint16_t power_w;
    bool hr_valid;
    bool cadence_valid;
    bool power_valid;

    /** @brief 当前圈序号（从 1 开始）。 */
    uint16_t lap_count;
    /** @brief 会话累计距离（米）— 用于公里标记。 */

static void rt_sys_gnss_to_fix(const myvendor_sys_gnss_t * src,
    bicycle_gnss_fix_t * out)
{
    uint8_t sats;

    if (src == NULL || out == NULL) {
        return;
    }

    memset(out, 0, sizeof(*out));
    out->alive = src->alive || src->valid;
    out->valid = src->valid;
    out->fix_quality = src->fix_quality;
    out->hdop_x10 = src->hdop_x10;
    out->rx_hz = src->rx_hz;
    sats = src->valid ? src->satellites : src->sats_heard;

    out->satellites = sats;
    if (!src->valid) {
        return;
    }

    out->latitude = (float)((double)src->lat_e7 / 10000000.0);
    out->longitude = (float)((double)src->lon_e7 / 10000000.0);
    out->course_deg = (float)src->course_deg;
    out->speed_kph = (float)src->speed_centi_kmh / 100.0f;
    if (src->fix_quality >= 2) {
        out->has_altitude = true;
        out->altitude_m = (float)src->alt_mm / 1000.0f;
    }
}

