__HAL_ROM_USED uint32_t HAL_QSPI_GET_CLK(FLASH_HandleTypeDef *fhandle)
{
    uint8_t div;
    uint32_t freq;

    if (NULL == fhandle)
        return 0;

    div = HAL_FLASH_GET_DIV(fhandle);
    if (div <= 0)
        return 0;

    freq = HAL_QSPI_GET_SRC_CLK(fhandle);
    freq /= div;

    return freq;
}
