        base = HAL_RCC_HCPU_GetDLL2Freq();
        break;
      case RCC_CLK_SRC_DLL1:
        base = HAL_RCC_HCPU_GetDLL1Freq();
        break;
      default:
        base = HAL_RCC_GetSysCLKFreq(CORE_ID_HCPU);
        break;
    }

  *hz = base / (*psclr != 0u ? *psclr : 1u);
}
