void myvendor_mtp_lfs_hold(void)
{
  int hold;

  pthread_mutex_lock(&g_mtp_lock);
  g_lfs_hold++;
  hold = g_lfs_hold;
  pthread_mutex_unlock(&g_mtp_lock);
  mtp_owner_info("myvendor_mtp: lfs_hold count=%d", hold);
  (void)hold;
}
void myvendor_mtp_lfs_release(void)
{
  pthread_mutex_lock(&g_mtp_lock);
  if (g_lfs_hold > 0)
    {
      g_lfs_hold--;
    }

  pthread_mutex_unlock(&g_mtp_lock);
}
bool myvendor_mtp_lfs_quiesce(void)
{
  bool q;

  pthread_mutex_lock(&g_mtp_lock);
  q = g_transfer_active || g_lfs_hold > 0
      || g_plug >= MYVENDOR_MTP_PLUG_ENUM || g_session;
  pthread_mutex_unlock(&g_mtp_lock);
  return q;
}

