  g_sd_fail_run = 0;

  if (g_sd_bus_hz != SF32LB_SD_TRAN_CLOCK_HZ)
    {
      sd1_set_clock(SF32LB_SD_TRAN_CLOCK_HZ);
      g_sd_bus_hz = SF32LB_SD_TRAN_CLOCK_HZ;
