             (unsigned long)i, (unsigned long long)off,
             (unsigned long long)(sd1_mono_us() - t0),
             buf[0], buf[1], buf[2], buf[3]);
    }

  nxmutex_unlock(&g_sd_lock);
  kmm_free(buf);

