static void diag_tick_one(struct diag_slot *s, uint32_t now)
{
  bool ok;
  uint32_t fail_ms;
  uint32_t cooldown;

  if (s->ops.ok == NULL)
    {
      return;
    }

  ok = s->ops.ok();
  if (ok)
    {
      s->fail_since_ms = 0;
      return;
    }

  if (s->fail_since_ms == 0)
    {
      s->fail_since_ms = now;
      syslog(LOG_WARNING, "diag: %s unhealthy\n", s->ops.name);
      return;
    }

  fail_ms = s->ops.fail_ms != 0 ? s->ops.fail_ms : 5000u;
  cooldown = s->ops.cooldown_ms != 0 ? s->ops.cooldown_ms : 15000u;
  if (diag_elapsed(now, s->fail_since_ms) < fail_ms)
    {
      return;
    }

  if (s->last_restart_ms != 0 &&
      diag_elapsed(now, s->last_restart_ms) < cooldown)
    {
      return;
    }

  syslog(LOG_ERR, "diag: %s restart (unhealthy %u ms, n=%u)\n",
         s->ops.name,
         (unsigned)diag_elapsed(now, s->fail_since_ms),
         (unsigned)(s->restarts + 1u));
  s->last_restart_ms = now;
  s->fail_since_ms = now;
  if (s->restarts < UINT16_MAX)
    {
      s->restarts++;
    }

  if (s->ops.restart != NULL)
    {
      (void)s->ops.restart();
    }
}

