static int g_lfs_minor;

/**
 * @brief /mnt/lfs 现在能不能用。
 *
 * @details 判据是 statfs 能否取到数 —— `df` 就是这么判的，所以"两个 LFS 从
 *          df 里消失"正是这个意思：挂载点还在，但超级块读不出来。
 *
 *          卡已判死时返回 true（“健康”）而不是 false：那是 SD 层的事，由判死
 *          + 硬复位负责。否则这里会去重挂一张根本不存在的卡，每一轮白试一次。
 */
bool sf32lb_sd_fs_ok(void)
{
  struct statfs st;

  if (g_sd_dead || !g_sd_initialized)
    {
      return true;
    }

  return statfs(SF32LB_SD_MOUNTPOINT, &st) == 0;
}

/**
 * @brief 重新挂载 /mnt/lfs。卡恢复之后 FS 不会自己回来，必须重挂。
 *
 * @details 为什么必须有这一步：硬复位把卡救回来时，我们只把 SD 层标成可用，
 *          但 LittleFS 的 RAM 内状态已经坏了、不会自愈 —— 于是后续每个文件
 *          系统调用继续失败。**"卡恢复了"不等于"FS 可用"**，这就是"运行中
 *          拔卡再插回来要能自动恢复"缺的那一环。
 *
 *          不要在持有 SD 总线锁的路径里调用：mount 内部还要走 SD I/O，
 *          g_sd_lock 不是可重入的，会自锁。只从 diag 线程调。
 *
 * @return 0 重挂成功；-EAGAIN 卡还没回来；其它负 errno 为失败。
 */
int sf32lb_sd_remount_lfs(void)
{
  int ret;

  if (g_sd_dead)
    {
      return -EAGAIN;
    }

  syslog(LOG_WARNING, "LFS: remount begin (card alive, FS was unusable)\n");

  if (umount(SF32LB_SD_MOUNTPOINT) != 0)
    {
      /* 没挂上/已不在挂载表都算正常，接着挂即可。 */
      syslog(LOG_WARNING, "LFS: umount(%s) errno=%d, continuing\n",
             SF32LB_SD_MOUNTPOINT, errno);
    }

  ret = sf32lb_sd_mount_littlefs(g_lfs_minor);
  if (ret == 0)
    {
      syslog(LOG_WARNING, "LFS: remount ok (minor=%d)\n", g_lfs_minor);
    }
  else
    {
      syslog(LOG_ERR, "LFS: remount FAILED ret=%d (minor=%d)\n",
             ret, g_lfs_minor);
    }

  return ret;
}

