            }

          stamp = (long)y * 10000000000L + (long)mo * 100000000L +
                  (long)d * 1000000L + (long)h * 10000L + (long)mi * 100L + (long)s;
          if (oldest_stamp == 0 || stamp < oldest_stamp)
            {
              oldest_stamp = stamp;
              snprintf(oldest, sizeof(oldest), "%s", de->d_name);
            }
        }

      closedir(dir);
    }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int myvendor_diaglog_start(void)
{
  time_t now = time(NULL);
  int    ret;

  if (g_started)
    {
      return 0;
    }

  ret = mkdir("/mnt/kv", 0755);
  if (ret < 0 && errno != EEXIST)
    {
      return -errno;
    }

  ret = mkdir(DIAGLOG_DIR, 0755);
  if (ret < 0 && errno != EEXIST)
    {
      return -errno;
    }

  /* 文件名带创建时刻：每次开机一个新文件；同一次开机跨天时 flush 会滚动。 */
  diaglog_mkpath(0, now);
  diaglog_prune();

  ret = syslog_channel_register(&g_diaglog_channel);
  if (ret < 0)
    {
      return ret;
    }

  g_started = true;

  /* 这一行本身也会进环，正好验证通道已经生效。 */
  syslog(LOG_INFO, "diaglog: RAM ring %u B -> %s (keep %u)\n",
         (unsigned)DIAGLOG_RING, DIAGLOG_DIR, (unsigned)DIAGLOG_KEEP);
  return 0;
}

int myvendor_diaglog_flush(void)
{
  uint32_t head;
  uint32_t tail;
  uint32_t n;
  int      fd;
  ssize_t  nw;

  if (!g_started)
    {
      return -EAGAIN;
    }

  /* 按天滚动：跨天后换新文件（同一次开机也就有了"一天一个"）。 */
  {
    time_t    now = time(NULL);
    struct tm tm;

    localtime_r(&now, &tm);
    if (tm.tm_yday != g_day)
      {
        diaglog_mkpath(tm.tm_yday, now);
        diaglog_prune();
      }
  }

  irqstate_t flags = up_irq_save();

  head = g_head;
  tail = g_tail;
  up_irq_restore(flags);

  if (head == tail)
    {
      return 0;
    }

  /* 一次 flush 最多写到环尾，剩下的下次继续，避免长时间占住总线。 */
  n = (head > tail) ? (head - tail) : (DIAGLOG_RING - tail);
  if (n > 2048u)
    {
      n = 2048u;
    }

  fd = open(g_path, O_WRONLY | O_CREAT | O_APPEND, 0644);
  if (fd < 0)
    {
      /* 写不了就保留在环里，下次再试；绝不因为日志失败去格式化或复位。 */
      return -errno;
    }

  nw = write(fd, &g_ring[tail], n);
  close(fd);

  if (nw <= 0)
    {
      return (nw == 0) ? 0 : -errno;
    }

  flags = up_irq_save();
  g_tail = (g_tail + (uint32_t)nw) % DIAGLOG_RING;
  up_irq_restore(flags);

  return (int)nw;
}

size_t myvendor_diaglog_snapshot(char *out, size_t n)
{
  uint32_t head;
  uint32_t tail;
  size_t   used = 0;

  if (out == NULL || n < 2u)
    {
      return 0;
    }

  head = g_head;
  tail = g_tail;
  if (head == tail)
    {
      out[0] = '\0';
      return 0;
    }

  /* 从 tail 到 head，按时间顺序拷出来。只做内存拷贝，可以在很差的环境里调用。 */
  while (tail != head && used + 1u < n)
    {
      out[used++] = g_ring[tail];
      tail = (tail + 1u) % DIAGLOG_RING;
    }

  out[used] = '\0';
  return used;
}
