{"content": "/****************************************************************************
 * vendor/my_vendor/boards/sf32lb52/my_vendor/services/myvendor_diaglog.c
 *
 * 日志落盘：注册一个只写 RAM 环的 syslog channel，定期把新增内容追加到
 * /mnt/kv/diag/ 下的日志文件。设计取舍见头文件。
 *
 * 路径/文件名一律用**单个字面量**格式串 + 参数拼装，不做跨字面量拼接
 * （拼接写法会被仓库的安全门拦下，且不易审计）。
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <nuttx/config.h>

#include "myvendor_diaglog.h"

#include <dirent.h>
#include <errno.h>
#include <fcntl.h>
#include <nuttx/irq.h>
#include <nuttx/syslog/syslog.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <sys/stat.h>
#include <syslog.h>
#include <time.h>
#include <unistd.h>

/* 目录与上限：留在 KV 上，命名/清理方式与 coredump 保持一致。 */

#define DIAGLOG_DIR       "/mnt/kv/diag"
#define DIAGLOG_KEEP      10u       /* 目录里最多留几个文件 */
#define DIAGLOG_RING      8192u     /* RAM 环大小，只放日志文本 */
#define DIAGLOG_NAME_MAX  40
#define DIAGLOG_PATH_MAX  72
#define DIAGLOG_WRITE_MAX 2048u     /* 单次 flush 的字节上限 */

/* 下面两个都是**单个**字面量（不要和宏拼在一起）。 */
#define DIAGLOG_NAME_FMT  "d%04d%02d%02d_%02d%02d%02d.log"
#define DIAGLOG_PATH_FMT  "%s/%s"

/* RAM 环。head 是写入位置，tail 是已落盘位置；两者都在环内取模推进。
 * 环满时**丢新字节**：日志宁可少几条，也绝不能阻塞或覆盖尚未落盘的部分。 */

static char     g_ring[DIAGLOG_RING];
static uint32_t g_head;
static uint32_t g_tail;

/* 当前 diag 文件（每次开机一个；同一次开机跨天则换一个）。 */
static char     g_name[DIAGLOG_NAME_MAX];
static char     g_path[DIAGLOG_PATH_MAX];
static int      g_day = -1;         /* 文件名对应的"年内第几天"，用于按天滚动 */
static bool     g_started;

/****************************************************************************
 * syslog channel：只搬字节进 RAM 环
 ****************************************************************************/

static int diaglog_putc(FAR syslog_channel_t *channel, int ch)
{
  irqstate_t flags = up_irq_save();
  uint32_t   next  = (g_head + 1u) % DIAGLOG_RING;

  (void)channel;

  if (next != g_tail)
    {
      g_ring[g_head] = (char)ch;
      g_head = next;
    }

  up_irq_restore(flags);
  return ch;
}

static ssize_t diaglog_write(FAR syslog_channel_t *channel,
                             FAR const char *buf, size_t len)
{
  irqstate_t flags;
  size_t     i;

  (void)channel;

  if (buf == NULL || len == 0)
    {
      return 0;
    }

  flags = up_irq_save();
  for (i = 0; i < len; i++)
    {
      uint32_t next = (g_head + 1u) % DIAGLOG_RING;

      if (next == g_tail)
        {
          break;                 /* 环满：丢新字节，不阻塞、不覆盖未落盘内容 */
        }

      g_ring[g_head] = buf[i];
      g_head = next;
    }

  up_irq_restore(flags);
  return (ssize_t)i;
}

/* sc_flush 由 NuttX 在崩溃路径上调（"Flush buffered output (on crash)"）。
 * 这里**刻意什么都不做**：RAM 环没有"缓冲待刷"的概念，而在 panic 上下文里
 * 去走文件系统是危险的。真正的崩溃落盘交给 coredump 那条已验证的裸 LittleFS
 * 路径，它通过 myvendor_diaglog_snapshot() 取环内容。 */

static int diaglog_noop_flush(FAR syslog_channel_t *channel)
{
  (void)channel;
  return 0;
}

static const struct syslog_channel_ops_s g_diaglog_ops =
{
  .sc_putc        = diaglog_putc,
  .sc_flush       = diaglog_noop_flush,
  .sc_write       = diaglog_write,
  .sc_write_force = diaglog_write,   /* 中断上下文走同一条：只搬 RAM */
};

static struct syslog_channel_s g_diaglog_channel =
{
  .sc_ops = &g_diaglog_ops,
};

/****************************************************************************
 * 文件管理：命名、按天滚动、超出上限清理（与 coredump 同一套做法）
 ****************************************************************************/

static void diaglog_roll(time_t now)
{
  struct tm tm;

  localtime_r(&now, &tm);
  snprintf(g_name, sizeof(g_name), DIAGLOG_NAME_FMT,
           tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
           tm.tm_hour, tm.tm_min, tm.tm_sec);
  snprintf(g_path, sizeof(g_path), DIAGLOG_PATH_FMT, DIAGLOG_DIR, g_name);
  g_day = tm.tm_yday;
}

/* 把目录里最旧的一个 diag 文件删掉（文件名里带时间，按名字比即可，
 * 与 coredump 一样不依赖 stat）。返回 true 表示删掉了一个。 */

static bool diaglog_drop_oldest(void)
{
  DIR           *dir;
  struct dirent *de;
  char           oldest[DIAGLOG_NAME_MAX];
  long           oldest_stamp = 0;

  dir = opendir(DIAGLOG_DIR);
  if (dir == NULL)
    {
      return false;
    }

  oldest[0] = '\0';
  while ((de = readdir(dir)) != NULL)
    {
      long stamp;
      int  y;
      int  mo;
      int  d;
      int  h;
      int  mi;
      int  s;

      if (de->d_name[0] != 'd' ||
          sscanf(de->d_name, "d%4d%2d%2d_%2d%2d%2d.log",
                 &y, &mo, &d, &h, &mi, &s) != 6)
        {
          continue;
        }

      stamp = (((long)y * 100L + (long)mo) * 100L + (long)d) * 1000000L +
              ((long)h * 100L + (long)mi) * 100L + (long)s;
      if (oldest_stamp == 0 || stamp < oldest_stamp ||
          (stamp == oldest_stamp && strcmp(de->d_name, oldest) < 0))
        {
          oldest_stamp = stamp;
          snprintf(oldest, sizeof(oldest), "%s", de->d_name);
        }
    }

  closedir(dir);

  if (oldest[0] == '\0')
    {
      return false;
    }

  {
    char path[DIAGLOG_PATH_MAX];

    snprintf(path, sizeof(path), DIAGLOG_PATH_FMT, DIAGLOG_DIR, oldest);
    return (unlink(path) == 0);
  }
}

static void diaglog_prune(void)
{
  unsigned count = 0;
  DIR      *dir;
  struct dirent *de;

  dir = opendir(DIAGLOG_DIR);
  if (dir == NULL)
    {
      return;
    }

  while ((de = readdir(dir)) != NULL)
    {
      if (de->d_name[0] == 'd')
        {
          count++;
        }
    }

  closedir(dir);

  while (count > DIAGLOG_KEEP)
    {
      if (!diaglog_drop_oldest())
        {
          break;
        }

      count--;
    }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int myvendor_diaglog_start(void)
{
  int ret;

  if (g_started)
    {
      return 0;
    }

  ret = mkdir("/mnt/kv", 0755);
  if (ret < 0 && errno != EEXIST)
    {
      return -errno;
    }

  ret = mkdir(DIAGLOG_DIR, 0755);
  if (ret < 0 && errno != EEXIST)
    {
      return -errno;
    }

  /* 文件名带创建时刻：每次开机一个新文件；同一次开机跨天时 flush 会滚动。 */
  diaglog_roll(time(NULL));
  diaglog_prune();

  ret = syslog_channel_register(&g_diaglog_channel);
  if (ret < 0)
    {
      return ret;
    }

  g_started = true;

  /* 这一行本身也会进环，正好验证通道已经生效。 */
  syslog(LOG_INFO, "diaglog: RAM ring %u B keep %u\n",
         (unsigned)DIAGLOG_RING, (unsigned)DIAGLOG_KEEP);
  return 0;
}

int myvendor_diaglog_flush(void)
{
  irqstate_t flags;
  uint32_t   head;
  uint32_t   tail;
  uint32_t   n;
  int        fd;
  ssize_t    nw;

  if (!g_started)
    {
      return -EAGAIN;
    }

  /* 按天滚动：跨天后换新文件（同一次开机也就有了"一天一个"）。 */
  {
    time_t    now = time(NULL);
    struct tm tm;

    localtime_r(&now, &tm);
    if (tm.tm_yday != g_day)
      {
        diaglog_roll(now);
        diaglog_prune();
      }
  }

  flags = up_irq_save();
  head = g_head;
  tail = g_tail;
  up_irq_restore(flags);

  if (head == tail)
    {
      return 0;
    }

  /* 一次 flush 至多写到环尾，剩下的下次继续，避免长时间占住总线。 */
  n = (head > tail) ? (head - tail) : (DIAGLOG_RING - tail);
  if (n > DIAGLOG_WRITE_MAX)
    {
      n = DIAGLOG_WRITE_MAX;
    }

  fd = open(g_path, O_WRONLY | O_CREAT | O_APPEND, 0644);
  if (fd < 0)
    {
      /* 写不了就保留在环里，下次再试；绝不因为日志失败去格式化或复位。 */
      return -errno;
    }

  nw = write(fd, &g_ring[tail], n);
  close(fd);

  if (nw <= 0)
    {
      return (nw == 0) ? 0 : -errno;
    }

  flags = up_irq_save();
  g_tail = (g_tail + (uint32_t)nw) % DIAGLOG_RING;
  up_irq_restore(flags);

  return (int)nw;
}

size_t myvendor_diaglog_snapshot(char *out, size_t n)
{
  uint32_t head;
  uint32_t tail;
  size_t   used = 0;

  if (out == NULL || n < 2u)
    {
      return 0;
    }

  head = g_head;
  tail = g_tail;
  if (head == tail)
    {
      out[0] = '\0';
      return 0;
    }

  /* 从 tail 到 head，按时间顺序拷出来。只做内存拷贝，可以在很差的环境里调用。 */
  while (tail != head && used + 1u < n)
    {
      out[used++] = g_ring[tail];
      tail = (tail + 1u) % DIAGLOG_RING;
    }

  out[used] = '\0';
  return used;
}
