36	/* 与 coredump 同一目录、同一套命名（前缀 D）。 */
37	
38	#define DIAGLOG_DIR        "/mnt/kv/coredump"
39	#define DIAGLOG_LFS_DIR    "/coredump"
40	#define DIAGLOG_KEEP       10u       /* 目录里最多留几个 d* 文件 */
41	#define DIAGLOG_RING      2048u      /* RAM 环大小，只放日志文本 */
42	#define DIAGLOG_NAME_MAX   48
43	#define DIAGLOG_PATH_MAX   80
44	#define DIAGLOG_WRITE_MAX  16384u    /* 单次 flush 的总预算（字节） */
45	#define DIAGLOG_SEQ_MAX    999u
46	
47	/* RAM 环。head 是写入位置，tail 是已落盘位置；两者都在环内取模推进。
48	 * 环满时**丢新字节**：日志宁可少几条，也绝不能阻塞或覆盖尚未落盘的部分。
49	 *
50	 * 尺寸刻意取小的 2 KB（"尽量落盘就好，不指望它能做什么"）。用它换算一下能扛多久：
51	 * 实测活跃期日志速率约 2~4 KB/s，而 flush 每个 diag tick（500 ms）一次，
52	 * 所以**环里能留住的是最近约 0.5~1 秒**的内容，超出的最新字节会被丢。
53	 * 真正累积下来的记录是**已经刷进文件的部分** —— 环只决定"刷新之前那零点几秒
54	 * 能丢多少"，不是总容量。刷屏期丢掉最新几行是设计上接受的。
55	 */
56	
57	static char     g_ring[DIAGLOG_RING];
58	static uint32_t g_head;
59	static uint32_t g_tail;
60	
61	static char     g_path[DIAGLOG_PATH_MAX];
62	static int      g_day = -1;          /* 文件名对应的"年内第几天"，用于按天滚动 */
63	static bool     g_started;
