68	
69	/* 把 v 按固定位数（零填充）写进 p，返回新的写指针。v 超出位数时按低位截断。 */
70	
71	static char *diaglog_put_u(char *p, unsigned v, unsigned width)
72	{
73	  unsigned i;
74	
75	  for (i = 0; i < width; i++)
76	    {
77	      unsigned digit = v;
78	      unsigned j;
79	
80	      /* 第 i 位 = v / 10^(width-1-i) 的个位；不用除法表，固定次数循环取。 */
81	      for (j = 0; j < (width - 1u - i); j++)
82	        {
83	          digit /= 10u;
84	        }
85	
86	      p[i] = (char)('0' + (digit % 10u));
87	    }
88	
89	  return p + width;
90	}
