92	/* 组一个 dNNN_YYYYMMDD_HHMMSS.txt 名字；seq 用 coredump 的计数器。 */
93	
94	static void diaglog_mkname(char *name, size_t n, unsigned seq, time_t now)
95	{
96	  struct tm tm;
97	  char     *p;
98	
99	  if (n < DIAGLOG_NAME_MAX)
100	    {
101	      name[0] = '\0';
102	      return;
103	    }
104	
105	  localtime_r(&now, &tm);
106	  if (tm.tm_year < 0)
107	    {
108	      memset(&tm, 0, sizeof(tm));
109	    }
110	
111	  p = name;
112	  *p++ = 'd';
113	  p = diaglog_put_u(p, seq % 1000u, 3u);
114	  *p++ = '_';
115	  p = diaglog_put_u(p, (unsigned)(tm.tm_year + 1900), 4u);
116	  p = diaglog_put_u(p, (unsigned)(tm.tm_mon + 1), 2u);
117	  p = diaglog_put_u(p, (unsigned)tm.tm_mday, 2u);
118	  *p++ = '_';
119	  p = diaglog_put_u(p, (unsigned)tm.tm_hour, 2u);
120	  p = diaglog_put_u(p, (unsigned)tm.tm_min, 2u);
121	  p = diaglog_put_u(p, (unsigned)tm.tm_sec, 2u);
122	  memcpy(p, ".txt", 5u);
123	
124	  g_day = tm.tm_yday;
125	}
