129	static void diaglog_mkpath(char *path, size_t n, const char *name)
130	{
131	  size_t d = strlen(DIAGLOG_DIR);
132	
133	  if (d + 1u + strlen(name) + 1u > n)
134	    {
135	      path[0] = '\0';
136	      return;
137	    }
138	
139	  memcpy(path, DIAGLOG_DIR, d);
140	  path[d] = '/';
141	  memcpy(path + d + 1u, name, strlen(name) + 1u);
