152	
153	  /* 形如 dNNN_ 之后是时间，长度至少到秒。 */
154	  if (name[0] != 'd' || strlen(name) < 24u)
155	    {
156	      return false;
157	    }
158	
159	  for (i = 0; i < 6u; i++)
160	    {
161	      unsigned j;
162	      long     acc = 0;
163	
164	      for (j = 0; j < wid[i]; j++)
165	        {
166	          char c = name[pos[i] + j];
167	
168	          if (c < '0' || c > '9')
169	            {
170	              return false;
171	            }
172	
173	          acc = acc * 10L + (long)(c - '0');
174	        }
175	
176	      v = v * 10000L + acc;
177	    }
178	
179	  *stamp = v;
180	  return true;
