204	static ssize_t diaglog_write(FAR syslog_channel_t *channel,
205	                             FAR const char *buf, size_t len)
206	{
207	  irqstate_t flags;
208	  size_t     i;
209	
210	  (void)channel;
211	
212	  if (buf == NULL || len == 0)
213	    {
214	      return 0;
215	    }
216	
217	  flags = up_irq_save();
218	  for (i = 0; i < len; i++)
219	    {
220	      uint32_t next = (g_head + 1u) % DIAGLOG_RING;
221	
222	      if (next == g_tail)
223	        {
224	          break;                 /* 环满：丢新字节，不阻塞、不覆盖未落盘内容 */
225	        }
226	
227	      g_ring[g_head] = buf[i];
228	      g_head = next;
229	    }
230	
231	  up_irq_restore(flags);
232	  return (ssize_t)i;
233	}
