355	{
356	  const char *seq_path = DIAGLOG_DIR "/seq_d";
357	  char        buf[16];
358	  int         fd;
359	  ssize_t     n;
360	  unsigned    v = 0;
361	  unsigned    i;
362	
363	  fd = open(seq_path, O_RDONLY);
364	  if (fd >= 0)
365	    {
366	      n = read(fd, buf, sizeof(buf) - 1u);
367	      close(fd);
368	      if (n > 0)
369	        {
370	          buf[n] = '\0';
371	          for (i = 0; i < (unsigned)n && buf[i] >= '0' && buf[i] <= '9'; i++)
372	            {
373	              v = v * 10u + (unsigned)(buf[i] - '0');
374	            }
375	        }
376	    }
377	
378	  v = (v + 1u) % (DIAGLOG_SEQ_MAX + 1u);
379	
380	  {
