444	int myvendor_diaglog_flush(void)
445	{
446	  irqstate_t flags;
447	  uint32_t   head;
448	  uint32_t   tail;
449	  uint32_t   n;
450	  int        fd;
451	  ssize_t    nw;
452	
453	  if (!g_started)
454	    {
455	      return -EAGAIN;
456	    }
457	
458	  /* 按天滚动：跨天后换一个文件（同一次开机也就有了"一天一个"）。 */
459	  {
460	    time_t    now = time(NULL);
461	    struct tm tm;
462	
463	    localtime_r(&now, &tm);
464	    if (tm.tm_yday != g_day)
465	      {
466	        char name[DIAGLOG_NAME_MAX];
467	
468	        diaglog_mkname(name, sizeof(name), diaglog_next_seq(), now);
469	        diaglog_mkpath(g_path, sizeof(g_path), name);
470	        diaglog_prune();
471	      }
472	  }
473	
474	  flags = up_irq_save();
475	  head = g_head;
476	  tail = g_tail;
477	  up_irq_restore(flags);
478	
479	  if (head == tail)
480	    {
481	      return 0;
482	    }
483	
484	  fd = open(g_path, O_WRONLY | O_CREAT | O_APPEND, 0644);
485	  if (fd < 0)
486	    {
487	      /* 写不了就保留在环里，下次再试；绝不因为日志失败去格式化或复位。 */
488	      return -errno;
489	    }
490	
491	  /* 一直写到环空为止，但受 DIAGLOG_WRITE_MAX 总预算约束。
492	   *
493	   * 早先的版本每个 tick 只写 2048 B（约 400 B/s），而实测活跃期日志速率是
494	   * 2~4 KB/s —— 入不敷出，环会长期满着、持续丢最新几行。现在按预算尽量写到空：
495	   * 正常速率下环几乎总是空的（内容基本立刻落盘），只有刷屏期才会丢，
496	   * 这也正是"尽量落盘、大量异常就算了"的语义。
497	   *
498	   * 每轮重新取 head，才能把本轮写入期间新产生的日志也一起带走。 */
499	
500	  {
501	    int total = 0;
502	
503	    while (total < (int)DIAGLOG_WRITE_MAX)
504	      {
505	        uint32_t n;
506	        ssize_t  nw;
507	
508	        flags = up_irq_save();
509	        head = g_head;
510	        tail = g_tail;
511	        up_irq_restore(flags);
512	
513	        if (head == tail)
514	          {
515	            break;
516	          }
517	
518	        n = (head > tail) ? (head - tail) : (DIAGLOG_RING - tail);
519	        if (n > (uint32_t)((int)DIAGLOG_WRITE_MAX - total))
520	          {
521	            n = (uint32_t)((int)DIAGLOG_WRITE_MAX - total);
522	          }
523	
524	        nw = write(fd, &g_ring[tail], n);
525	        if (nw <= 0)
526	          {
527	            if (total == 0)
528	              {
529	                close(fd);
530	                return (nw == 0) ? 0 : -errno;
531	              }
532	
533	            break;
534	          }
535	
536	        flags = up_irq_save();
537	        g_tail = (g_tail + (uint32_t)nw) % DIAGLOG_RING;
538	        up_irq_restore(flags);
539	        total += (int)nw;
540	      }
541	
542	    close(fd);
543	    return total;
544	  }
545	}
