547	size_t myvendor_diaglog_snapshot(char *out, size_t n)
548	{
549	  uint32_t head;
550	  uint32_t tail;
551	  size_t   used = 0;
552	
553	  if (out == NULL || n < 2u)
554	    {
555	      return 0;
556	    }
557	
558	  head = g_head;
559	  tail = g_tail;
560	  if (head == tail)
561	    {
562	      out[0] = '\0';
563	      return 0;
564	    }
565	
566	  /* 从 tail 到 head，按时间顺序拷出来。只做内存拷贝，可以在很差的环境里调用。 */
567	  while (tail != head && used + 1u < n)
568	    {
569	      out[used++] = g_ring[tail];
570	      tail = (tail + 1u) % DIAGLOG_RING;
571	    }
572	
573	  out[used] = '\0';
574	  return used;
575	}
