      (void)lfs_dir_close(&g_crash_lfs, &dir);
      if (count <= keep || oldest[0] == '\0')
        {
          return;
        }

      snprintf(path, sizeof(path), COREDUMP_DIR_LFS "/%s", oldest);
      (void)lfs_remove(&g_crash_lfs, path);
    }
