{"content": "/* 主机侧测试：直接 #include 真实源码，验证级别过滤。
 * 只桩掉 up_irq_save/restore、syslog_channel_register 和 nuttx 头文件，
 * 过滤器本身（含行状态机、记号匹配、转义丢弃、续行继承）是**真实代码**。
 *
 * 用法: cc -I. -I<stub dir> test_diaglog.c -o t && ./t
 */

#include <stdio.h>
#include <string.h>
#include <syslog.h>

unsigned int g_stub_irq_nesting;
int          g_fail;

int syslog_channel_register(void *channel)
{
  (void)channel;
  return 0;
}

/* 把真实实现整块拉进来，这样测的就是发出去的那份代码 */
#include "myvendor_diaglog.c"

/* ---- 复刻板子上的真实输出格式 ----
 * 顺序（vsyslog.c）："\e[0m" + "[ts] " + ("[CPU%d] ") + ("[%2d] ") +
 *                    <color> + "[%6s] " + message
 * 带颜色和不带颜色两种都测，证明匹配不依赖 ANSI 序列。 */

static void emit(const char *s)
{
  diaglog_write(&g_diaglog_channel, s, strlen(s));
}

static void emit_crlf_split(const char *body)
{
  /* 模拟 CONFIG_SYSLOG_CRLF 下 syslog_write_foreach 的两次 write */
  emit(body);
  emit("\r\n");
}

static void reset(void)
{
  g_head = g_tail = 0;
  g_pfx_len = 0;
  g_decided = false;
  g_keep    = false;
  g_in_esc  = false;
  g_started = true;
  g_path[0] = '/';   /* flush 之外不会被用到，占位避免空串 */
}

static void check(const char *what, const char *expect_sub, int want_present)
{
  static char buf[4096];
  size_t      n;
  int         found;

  n = myvendor_diaglog_snapshot(buf, sizeof(buf));
  found = (n > 0) && (strstr(buf, expect_sub) != NULL);

  if (found == want_present)
    {
      printf("  OK   %-52s (%s)\n", what, want_present ? "留存" : "丢弃");
    }
  else
    {
      printf("  FAIL %-52s 期望%s，实际环内容:\n---\n%s\n---\n",
             what, want_present ? "留存" : "丢弃", buf);
      g_fail = 1;
    }
}

#define C_RED   "\x1b[31m"
#define C_WARN  "\x1b[33m"
#define C_RESET "\x1b[0m"
#define TS      "\x1b[0m[2026-09-16 17:39:41.123456] "

int main(void)
{
  char line[512];

  printf("== 级别过滤 ==\n");

  reset();
  emit_crlf_split(TS C_RED "[ ERROR] SD: CMD18 addr=0x0 n=8 FAILED after 4 tries (sr=0x1 why=noerr_but_cmd_busy)");
  check("ERROR 行留存", "CMD18", 1);
  check("  —— 且已剥掉 ANSI 转义", "\x1b[", 0);

  reset();
  emit_crlf_split(TS C_WARN "[  WARN] SD: hard reset #1 (interface down 200 ms)");
  check("WARN 行留存（恢复叙事全靠它）", "hard reset #1", 1);

  reset();
  emit_crlf_split(TS "[  WARN] SD: RECOVERED by hard reset #2 (was dead 30000 ms)");
  check("无颜色时 WARN 也能识别", "RECOVERED", 1);

  reset();
  emit_crlf_split(TS "[  INFO] gnss: rt 120 eph-psram-done +1 ms");
  check("INFO 行丢弃", "eph-psram-done", 0);

  reset();
  emit_crlf_split(TS "[ DEBUG] ble: tick 42");
  check("DEBUG 行丢弃", "tick", 0);

  reset();
  emit_crlf_split(TS "[NOTICE] LFS: mount begin dev=/dev/sdkv");
  check("NOTICE 行丢弃", "mount begin", 0);

  printf("== 多行消息：续行继承 ==\n");

  reset();
  emit_crlf_split(TS C_RED "[ ERROR] LFS: mount FAILED after 3 tries");
  emit_crlf_split("             last_errno=-5");
  emit_crlf_split("             giving up on this attempt");
  check("ERROR 的第一行留存", "mount FAILED", 1);
  check("ERROR 的续行也留存", "last_errno=-5", 1);
  check("ERROR 的第三行也留存", "giving up", 1);

  reset();
  emit_crlf_split(TS "[  INFO] df: /mnt/kv 256M");
  emit_crlf_split("             /mnt/lfs 512M");
  check("INFO 的续行一起丢弃", "/mnt/lfs", 0);

  printf("== 状态在 INFO 之后能复位 ==\n");

  reset();
  emit_crlf_split(TS "[  INFO] noise 1");
  emit_crlf_split(TS C_RED "[ ERROR] real problem");
  emit_crlf_split(TS "[  INFO] noise 2");
  check("中间的 ERROR 留存", "real problem", 1);
  check("ERROR 之前的 INFO 不在", "noise 1", 0);
  check("ERROR 之后的 INFO 不在", "noise 2", 0);

  printf("== 逐字节 putc 与整块 write 等价 ==\n");

  reset();
  {
    const char *s = TS C_RED "[ ERROR] byte at a time";
    size_t      i;

    for (i = 0; i < strlen(s); i++)
      {
        diaglog_putc(&g_diaglog_channel, (unsigned char)s[i]);
      }

    emit("\r\n");
  }
  check("逐字节喂入同样留存", "byte at a time", 1);

  printf("== 记号跨写入边界也能认出 ==\n");

  reset();
  emit(TS C_RED "[ ERR");
  emit("OR] split across two writes");
  emit("\r\n");
  check("记号被切成两次 write 仍留存", "split across", 1);

  reset();
  emit(TS "[  IN");
  emit("FO] split info");
  emit("\r\n");
  check("INFO 记号被切开也不误收", "split info", 0);

  printf("== 超长无记号文本不越界/不误收 ==\n");

  reset();
  {
    char big[300];

    memset(big, 'x', sizeof(big) - 1u);
    big[sizeof(big) - 1u] = '\0';
    emit(big);
    emit("\r\n");
    check("裸长文本（无记号）丢弃", "xxxx", 0);
  }

  reset();
  emit("boot banner without any token at all\r\n");
  check("裸短文本丢弃", "boot banner", 0);

  printf("== 环满时丢新字节、不覆盖 ==\n");

  reset();
  {
    int i;

    for (i = 0; i < 200; i++)
      {
        snprintf(line, sizeof(line), TS "[ ERROR] filler %03d\r\n", i);
        emit(line);
      }

    check("环满后最早的仍在", "filler 000", 1);
    check("环满后最新的被丢", "filler 199", 0);
  }

  printf("\n%s\n", g_fail ? "有失败" : "全部通过");
  return g_fail;
}
