static void gnss_sleep_us(uint32_t us)
{
  uint32_t budget;
  uint32_t cyc0;
  uint32_t spins = 0;
  struct sched_param prio0;
  int policy0 = 0;
  bool have0;

  if (us == 0)
    {
      return;
    }

  budget = gnss_cycles_budget_us(us);
  if (budget == 0)
    {
      usleep(us);
      return;
    }

  /* 原优先级在**入口取一次**，不在自旋循环里取。
   *
   * 循环里取到的是"我们刚刚降下去的最低优先级"，于是 low=1、恢复也回 1 ——
   * 一次恢复失败就会把最低优先级当成原值永久固化（`ps` 里看到的
   * `gnss pri=1`）。在入口取就没有这个自我引用的机会。 */
  have0 = (pthread_getschedparam(pthread_self(), &policy0, &prio0) == 0);

  cyc0 = gnss_cycles_now();
  for (;;)
    {
      if ((uint32_t)(gnss_cycles_now() - cyc0) >= budget)
        {
          return;
        }

      if (++spins > GNSS_SLEEP_SPIN_MAX)
        {
          return;
        }

