static void slot_try_connect(struct sensor_slot *slot, uint32_t now_ms)
{
  bt_status_t ret;

  if (!g_allow_connect && !slot->want_link)
    {
      return;
    }

  if (g_scan_until_ms != 0)
    {
      return;
