static bool rt_still_update(float step_m, uint32_t now, bool reset)
{
    static float acc_m;          /* 自锚点起的累计位移 */
    static uint32_t still_at;    /* 进入静止的时刻（0 = 未静止） */
    static bool still;

    if (reset) { acc_m = 0.0f; still_at = 0; still = false; return false; }

    acc_m += step_m;

    if (still) {
        if (acc_m >= RT_STILL_EXIT_M) {        /* 真走了 → 退出静止，重新锚定 */
            still = false;
            still_at = 0;
            acc_m = 0.0f;
        }
        return still;                          /* 仍在静止：调用方不要累加 */
    }

    if (acc_m < RT_STILL_ENTER_M) {            /* 还在噪声半径内 */
        if (still_at == 0) still_at = now ? now : 1u;
        else if ((now - still_at) >= RT_STILL_HOLD_MS) { still = true; acc_m = 0.0f; }
    } else {
        still_at = 0;                          /* 走开了 → 重新计时 */
        acc_m = 0.0f;                          /* 重新锚定 */
    }

    return still;
